/* ============================================================
   Template: Main Large Screen
   Spec: 02-design/specs/templates/template-main-large-screen.md
   Token source: library (../../../library/common.css)
   ============================================================ */

*, *::before, *::after { box-sizing: border-box; }

body {
  margin: 0;
  padding: 0;
  background: var(--zimm-color-bg-01);
}

/* Skip link */
.skip-link {
  position: absolute;
  left: 0;
  top: 0;
  transform: translateY(-100%);
  padding: var(--zimm-scale-300) var(--zimm-scale-400);
  background: var(--zimm-color-bg-01);
  color: var(--zimm-color-text-01);
  font-family: var(--zimm-font-family-body);
  font-size: var(--zimm-font-size-3xs);
  text-decoration: none;
  z-index: 9999;
  transition: transform 200ms ease;
}

.skip-link:focus {
  transform: translateY(0);
  outline: 2px solid var(--zimm-color-text-01);
  outline-offset: 2px;
}

/* Page shell — 4 regions stacked with 12px gap (Figma layout gap) */
.page-shell {
  display: flex;
  flex-direction: column;
  gap: 12px; /* token candidate: --zimm-template-region-gap */
  min-height: 100vh;
}

.region {
  display: block;
  width: 100%;
}

/* ---- Logo masthead region ---- */
/* Placeholder for zimm-logo-masthead. Figma: 1892:49809. Height 114px, logo pinned bottom-left. */
.region-logo-masthead {
  background: var(--zimm-color-bg-01);
  height: 114px;
  display: flex;
  align-items: flex-end;
  padding: 0 0 var(--zimm-scale-1000) var(--zimm-scale-1000);
}

.logo-masthead-img {
  display: block;
  width: 631px;
  height: auto;
  max-width: 100%;
}

/* ---- Main content region ---- */
.region-content {
  min-height: 141px;
  background: var(--zimm-color-bg-01);
}

/* ---- Responsive ---- */
/* Navigation and Footer handle their own breakpoints internally via shadow DOM @media. */
/* Logo masthead: scale wordmark proportionally on smaller viewports. */

@media (max-width: 1023px) {
  .logo-masthead-img {
    width: 60%;
  }
}

@media (max-width: 767px) {
  .logo-masthead-img {
    width: 80%;
  }

  .region-logo-masthead {
    padding: 0 0 var(--zimm-scale-800) var(--zimm-scale-800);
  }
}

