/* Android / Material Design 3 Platform Styles
   Reference layer for Android prototypes. Use alongside project tokens from common.css.
   Do not override library token values here, use these as guardrail references.
   Based on Material Design 3 (Material You).
   ------------------------------------------ */

:root {

  /* Typography
